using EduHelpdesk.Models; using EduHelpdesk.Services; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages;
namespace EduHelpdesk.Pages.Settings;
public class OptionModel(HelpdeskStore store):PageModel
{
 public string Kind {get;set;}=""; public IReadOnlyList<string> Values=>Kind switch{"Teams" or "Team"=>store.TechnicianTeams,"Departments" or "Department"=>store.Departments,"Locations" or "Location"=>store.Locations,"AssetTypes" or "Asset type"=>store.AssetTypes,"AssetMakes" or "Asset make"=>store.AssetMakes,"AssetModels" or "Asset model"=>store.AssetModels,"AssetStatuses" or "Asset status"=>store.AssetStatuses,"Categories" or "Category"=>store.Categories,"Statuses" or "Status"=>store.Statuses,"Priorities" or "Priority"=>store.Priorities,"PartCategories" or "Part category"=>store.PartCategories,"PartLocations" or "Part location"=>store.PartLocations,"LoanReasons" or "Loan reason"=>store.LoanReasons,"PurchasingRequirements" or "Purchasing requirement"=>store.PurchasingRequirements,"Buildings" or "Building"=>store.Buildings,"AssetConditions" or "Asset condition"=>store.AssetConditions,"ContractTypes" or "Contract type"=>store.ContractTypes,"SpendCategories" or "Spend category"=>store.SpendCategories,"ContractDurations" or "Contract duration"=>store.ContractDurations,"ContractStatuses" or "Contract status"=>store.ContractStatuses,"PersonTypes" or "Person type"=>store.PersonTypes,"AccessCategories" or "Access category"=>store.AccessCategories,"RevokeReasons" or "Revoke reason"=>store.RevokeReasons,"BudgetCodes" or "Budget code"=>store.BudgetCodes,"Cleaners" or "Cleaner"=>store.Cleaners,_=>[]};
 // Categories and teams each belong to a desk (HelpdeskStore.Desks). The picker only shows once there is more than one.
 public bool PlacedOnDesks=>Kind is "Categories" or "Teams" && store.HasSeveralDesks;
 public IReadOnlyList<Desk> Desks=>store.Desks;
 public Desk? DeskFor(string value)=>Kind switch{"Categories"=>store.DeskForCategory(value),"Teams"=>store.DeskForTeam(value),_=>null};
 public bool CanOpenSettings=>store.UserCan(User,Modules.Settings,ModulePermission.Access);
 // Cleaners and Budget codes also open for "Set up facilities" alone (Modules.FacilitiesSetupPages). The kind comes from
 // the form, so without Settings: Edit a post may only touch the list this page is for - not Categories, say.
 private static readonly Dictionary<string,string> FacilitiesKinds=new(StringComparer.OrdinalIgnoreCase){["/Settings/Cleaners"]="Cleaners",["/Settings/BudgetCodes"]="BudgetCodes"};
 private bool MayChange(string kind)=>store.UserCan(User,Modules.Settings,ModulePermission.Edit)||(FacilitiesKinds.TryGetValue(PageContext.ActionDescriptor.ViewEnginePath,out var own)&&string.Equals(own,kind,StringComparison.Ordinal));
 public void OnGet(string kind){Kind=kind;}
 public IActionResult OnPost(string kind,string value,string? currentValue,Guid? deskId){if(!MayChange(kind))return Forbid(); Kind=kind; if(string.IsNullOrWhiteSpace(value)){ModelState.AddModelError("","A value is required.");return Page();} var ticketKind = NormalizeTicketKind(kind); TempData["Message"] = ticketKind is null ? (currentValue is null ? store.AddManagedOption(kind,value,deskId) : store.UpdateManagedOption(kind,currentValue,value)) : (currentValue is null ? store.AddTicketOption(ticketKind,value,deskId) : store.UpdateTicketOption(ticketKind,currentValue,value)); return RedirectToPage(new{kind});}
 public IActionResult OnPostDelete(string kind,string value){if(!MayChange(kind))return Forbid(); var ticketKind = NormalizeTicketKind(kind); TempData["Message"] = ticketKind is null ? store.DeleteManagedOption(kind,value) : store.DeleteTicketOption(ticketKind,value); return RedirectToPage(new{kind});}
 // Moves a category (with its open tickets) or a team (with its people) to another desk.
 public IActionResult OnPostDesk(string kind,string value,Guid deskId){if(!store.UserCan(User,Modules.Settings,ModulePermission.Edit))return Forbid(); TempData["Message"] = kind switch{"Categories"=>store.SetCategoryDesk(value,deskId).Message,"Teams"=>store.SetTeamDesk(value,deskId).Message,_=>"Only categories and teams sit on a desk."}; return RedirectToPage(new{kind});}
 private static string? NormalizeTicketKind(string kind) => kind switch { "Categories" => "Category", "Statuses" => "Status", "Priorities" => "Priority", _ => null };
}
